const state = $json;
const THEME = 'Does a real trading edge exist in Polymarket BTC 5m markets or is it a data illusion?';
if (state.season_id !== 'S1') throw new Error('season_id must remain S1');
if (state.season_theme !== THEME) throw new Error('season theme mismatch');
if (!String(state.open_loop || '').trim().endsWith('?')) throw new Error('stored open_loop must be a question');
if (state.continuation_required !== true) throw new Error('continuation_required must be true');
const match = /^S1E(\d+)$/.exec(String(state.episode_id || ''));
if (!match) throw new Error('invalid episode_id');
const nextEpisode = `S1E${String(Number(match[1]) + 1).padStart(2, '0')}`;
const prompt = `You are the serialized investigative editor for ForgeView Probability Lab.

SEASON QUESTION:
${THEME}

PREVIOUS STATE:
${JSON.stringify(state, null, 2)}

Generate exactly one next episode. It MUST depend on the previous open_loop, introduce a contradiction, partially resolve the prior uncertainty, evolve belief_state, append one new contradiction, and end with a NEW unresolved question. Never fully resolve the season question.

Tone: Bloomberg terminal realism, Netflix investigative tension, AI financial experiment. Viewer language, no unexplained statistics. Research only. No trading instruction.

Return strict JSON only with this exact shape:
{
  "episode_id": "${nextEpisode}",
  "narrative_hook": "conflict-first hook",
  "breakdown": "system failure or insight shift",
  "partial_resolution": "what part of the previous open loop is answered",
  "telegram_post": "complete Telegram post",
  "x_post": "X post under 280 characters",
  "scenes": [
    {"scene_id":"scene_1","prompt":"production-ready Kling prompt","duration_seconds":10},
    {"scene_id":"scene_2","prompt":"production-ready Kling prompt","duration_seconds":10},
    {"scene_id":"scene_3","prompt":"production-ready Kling prompt","duration_seconds":10},
    {"scene_id":"scene_4","prompt":"production-ready Kling prompt","duration_seconds":10}
  ],
  "belief_state_update": "new belief after this result",
  "open_loop": "new unresolved question ending with ?",
  "last_result": "latest experiment outcome",
  "new_contradiction": "one newly broken assumption",
  "next_trigger": "what evidence should trigger the following episode"
}

All four scenes must express the same narrative transition. The final Telegram sentence and final scene must ask the new open_loop question.`;
return [{ json: { state, next_episode_id: nextEpisode, prompt } }];

const prepared = $('Prepare Narrative Request').first().json;
const raw = $json.message?.content ?? $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.content ?? $json.text ?? $json;
let generated;
if (typeof raw === 'string') {
  const cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/\s*```$/, '');
  generated = JSON.parse(cleaned);
} else {
  generated = raw;
}
const required = ['episode_id','narrative_hook','breakdown','partial_resolution','telegram_post','x_post','belief_state_update','open_loop','last_result','new_contradiction','next_trigger'];
for (const field of required) {
  if (!String(generated[field] ?? '').trim()) throw new Error(`Missing generated field: ${field}`);
}
if (generated.episode_id !== prepared.next_episode_id) throw new Error('episode_id continuity failure');
if (!Array.isArray(generated.scenes) || generated.scenes.length !== 4) throw new Error('Exactly four scenes are required');
if (!String(generated.open_loop).trim().endsWith('?')) throw new Error('open_loop must end with a question');
if (String(generated.open_loop).trim() === String(prepared.state.open_loop).trim()) throw new Error('A new open_loop is required');
if (String(generated.belief_state_update).trim() === String(prepared.state.belief_state).trim()) throw new Error('belief_state must evolve');
if (String(generated.telegram_post).length > 4096) throw new Error('Telegram post exceeds 4096 characters');
if ([...String(generated.x_post)].length > 280) throw new Error('X post exceeds 280 characters');
const chain = [...(prepared.state.contradiction_chain || [])];
if (!chain.includes(generated.new_contradiction)) chain.push(generated.new_contradiction);
return [{ json: {
  ...generated,
  season_id: 'S1',
  season_theme: prepared.state.season_theme,
  previous_episode_id: prepared.state.episode_id,
  previous_open_loop: prepared.state.open_loop,
  contradiction_chain: chain,
  continuation_required: true,
  generated_at: new Date().toISOString()
} }];

const requests = $json.scenes.map((scene, index) => ({
  scene_id: scene.scene_id || `scene_${index + 1}`,
  provider: 'kling',
  mode: 'ready_for_upload',
  request: {
    model_name: 'kling-v2-6',
    prompt: String(scene.prompt || ''),
    negative_prompt: 'unreadable text, distorted monitors, logos, watermarks, crypto coins, rockets, luxury cars, hooded hackers, trading advice',
    mode: 'pro',
    duration: String(scene.duration_seconds || 10),
    aspect_ratio: '9:16',
    external_task_id: `${$json.episode_id}_${scene.scene_id || index + 1}`
  }
}));
return [{ json: {
  episode_id: $json.episode_id,
  created_at: new Date().toISOString(),
  status: 'ready_for_upload',
  provider: 'kling',
  async: true,
  requests
} }];
